if (!actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "in_water")) return;
if (args.move && (args.move.id === "opportunity-attack" || args.move.id === "opportunity")) {
    args.output.abort = true;
    ui.notifications.info(`${actor.name} 身处水中，未被趁虚而入！`);
}

// 拥有“身处水中”效果时：速度+5
