let records = actor.getFlag("xjzl-system", "xumingRecords") || [];
let recordCombatId = actor.getFlag("xjzl-system", "xumingCombatId");
let currentCombatId = game.combat ? game.combat.id : "none";

if (recordCombatId !== currentCombatId) {
    records =[];
    recordCombatId = currentCombatId;
}

// 3. 投掷 D12
const roll = await new Roll("1d12").evaluate();
if (game.dice3d) game.dice3d.showForRoll(roll, game.user, true);
const result = roll.total;

let isDuplicate = records.includes(result);
if (!isDuplicate) {
    // 没重复：阻止濒死
    records.push(result);
    await actor.setFlag("xjzl-system", "xumingRecords", records);
    await actor.setFlag("xjzl-system", "xumingCombatId", currentCombatId);
